mapper.select:
SELECT
FROM manhole_cover mc -- 关联监测表（核心） INNER JOIN manhole_monitor mm ON mc.id = mm.cover_id AND mm.deleted = 0 AND mm.tenant_id = 1 -- 关联道路表 LEFT JOIN road_facility rf ON mc.road_id = rf.id AND rf.tenant_id = 1 -- 关联开合状态字典表 LEFT JOIN sys_open_status sos ON mm.open_status_id = sos.id -- 关联风险等级字典表 LEFT JOIN sys_risk_level srl ON mm.risk_level_id = srl.id -- 关联设备表 LEFT JOIN sys_device sd ON mm.device_id = sd.id AND sd.tenant_id = 1 -- 关联运维人员表 LEFT JOIN sys_user su ON mm.staff_id = su.id AND su.tenant_id = 1 -- 关联配置表 LEFT JOIN manhole_config mhc ON mc.id = mhc.cover_id WHERE 1=1 AND mc.deleted = 0 AND mc.tenant_id = 1
AND rf.road_name LIKE CONCAT('%', #{roadName}, '%')
AND sos.status_name = #{statusName}
AND sd.online_status = #{onlineStatus}
AND mc.cover_no LIKE CONCAT('%', #{coverNo}, '%')
AND mm.monitor_status = #{monitorStatus}
AND mm.risk_level_id = #{riskLevel}
ORDER BY mm.update_time DESC

mapper.update:
UPDATE sys_device SET online_status = #{onlineStatus}, update_time = NOW(), updater = 1 WHERE id IN ( SELECT device_id FROM manhole_monitor WHERE cover_id IN
#{coverId}
)
